HARBOR_STATE = {"dlv": "delivered", "dll": "delivered_late", "can": "cancelled",
                "ret": "returned", "hld": "held"}
FW_STATE = {"D": "delivered", "L": "delivered_late", "C": "cancelled",
            "R": "returned", "H": "held"}


def read_text(path):
    b = open(path, "rb").read()
    if b[:2] == b"\x1f\x8b":
        b = gzip.decompress(b)
    if b[:3] == b"\xef\xbb\xbf":
        s = b[3:].decode("utf-8", "replace")
    elif b[:2] == b"\xff\xfe":
        s = b[2:].decode("utf-16-le", "replace")
    elif b[:2] == b"\xfe\xff":
        s = b[2:].decode("utf-16-be", "replace")
    else:
        enc = "utf-8"
        m = re.search(rb"^[ \t]*#[ \t]*charset[ \t]*[:=][ \t]*([A-Za-z0-9_.:-]+)",
                      b[:2000], re.M | re.I)
        if m:
            enc = m.group(1).decode("ascii")
            try:
                "".encode(enc)
            except LookupError:
                enc = "utf-8"
        s = b.decode(enc, "replace")
    return s.replace("\r\n", "\n").replace("\r", "\n")


def id_num(s):
    m = re.search(r"\d+", s or "")
    return int(m.group()) if m else None


def norm_status(s):
    return re.sub(r"[ \-]+", "_", (s or "").strip().lower())


def rec_type(s):
    s = (s or "").strip().lower()
    if s.startswith("v"):
        return "void"
    if s.startswith(("c", "a")):
        return "correction"
    return "new"


def num(s):
    s = s.strip().replace(",", "").replace(" ", "")
    return Decimal(s)


def parse_weight(raw, unit, decimal_comma=False):
    """raw may carry its own unit suffix. Returns kg Decimal or None."""
    raw = (raw or "").strip()
    if not raw:
        return None
    m = re.fullmatch(r"(.*?)\s*(kg|g|lb|oz)", raw, re.I)
    if m:
        raw, unit = m.group(1), m.group(2).lower()
    if decimal_comma:
        raw = raw.replace(".", "").replace(",", ".")
    try:
        return num(raw) * KG[(unit or "kg").lower()]
    except (InvalidOperation, KeyError):
        return None


def parse_ship(v, form):
    """Return (year, month) in UTC or None."""
    v = (v or "").strip()
    if not v:
        return None
    m = re.fullmatch(r"(\d{4})-(\d\d)-(\d\d)(?:[T ](\d\d):(\d\d)(?::(\d\d)(?:\.\d+)?)?"
                     r"\s*(Z|[+-]\d\d(?::?\d\d)?)?)?", v, re.I)
    if m:
        y, mo, d, hh, mi, ss, tz = m.groups()
        if hh is None:
            return int(y), int(mo)
        t = dt.datetime(int(y), int(mo), int(d), int(hh), int(mi), int(ss or 0))
        if tz and tz.upper() != "Z":
            sign = 1 if tz[0] == "+" else -1
            digits = tz[1:].replace(":", "")
            off = dt.timedelta(hours=int(digits[:2]), minutes=int(digits[2:] or 0))
            t -= sign * off
        return t.year, t.month
    m = re.fullmatch(r"(\d{1,2}) ([A-Za-z]{3})[a-z]* (\d{4})", v)
    if m:
        return int(m.group(3)), MONTHS[m.group(2).lower()]
    m = re.fullmatch(r"(\d{4})(\d{3})", v)
    if m:
        d = dt.date(int(m.group(1)), 1, 1) + dt.timedelta(days=int(m.group(2)) - 1)
        return d.year, d.month
    m = re.fullmatch(r"(\d{4})(\d\d)(\d\d)", v)
    if m:
        return int(m.group(1)), int(m.group(2))
    m = re.fullmatch(r"(\d{1,2})\.(\d{1,2})\.(\d{4})", v)
    if m:
        return int(m.group(3)), int(m.group(2))
    m = re.fullmatch(r"(\d+)(?:\.\d+)?", v)
    if m and (form or "").lower() == "serial":
        d = dt.date(1899, 12, 31) + dt.timedelta(days=int(m.group(1)))
        if int(m.group(1)) >= 60:
            d -= dt.timedelta(days=1)
        return d.year, d.month
    m = re.fullmatch(r"(\d{1,4})[-/.](\d{1,2})[-/.](\d{1,4})", v)
    if m:
        a, b, c = m.groups()
        f = (form or "").upper().replace("-", "/").replace(".", "/")
        if f in ("DMY", "DD/MM/YYYY"):
            return int(c), int(b)
        if f in ("MM/DD/YYYY", "MDY"):
            return int(c), int(a)
        if len(a) == 4:
            return int(a), int(b)
        return int(c), int(b)
    return None


def doy_ship(v):
    return parse_ship(v, None)


# ---------------------------------------------------------------- readers
def comment_directive(line):
    m = re.match(r"#\s*([^:=]+?)\s*:\s*(.*?)\s*$", line)
    return (m.group(1).strip().lower(), m.group(2)) if m else None


def logical_lines(text):
    """Yield (is_comment, text) for physical/logical lines, joining quoted lines."""
    buf = None
    for line in text.split("\n"):
        if buf is None:
            if not line.strip():
                continue
            if line.startswith("#"):
                yield True, line
                continue
            buf = line
        else:
            buf += "\n" + line
        if buf.count('"') % 2 == 0:
            yield False, buf
            buf = None
    if buf is not None:
        yield False, buf


def read_delimited(depot, text):
    delim = DELIM[depot]
    cols = COLS[depot]
    seq = None
    directives = {}
    header = None
    out = []
    for is_comment, line in logical_lines(text):
        if is_comment:
            m = re.search(r"seq\s*[:=]?\s*(\d+)", line, re.I)
            if m and seq is None:
                seq = int(m.group(1))
            d = comment_directive(line)
            if d:
                directives[d[0]] = d[1]
            continue
        if depot in ("east", "lakeside"):
            row = next(csv.reader([line], delimiter=delim))
        else:
            row = line.split(delim)
        low = [c.strip().lower() for c in row]
        if low and all(c in cols for c in low) and len(low) >= 2:
            header = low
            continue
        if header is None:
            continue
        out.append((header, row, dict(directives)))
    return seq, out


def unit_of(s):
    m = re.match(r"\s*(kg|g|lb|oz)\b", s or "", re.I)
    return m.group(1).lower() if m else None


def wcol(header):
    for i, h in enumerate(header):
        if h in ("gross", "weight") or re.fullmatch(r"gross_(kg|g|lb|oz)|weight_(kg|g|lb|oz)", h):
            return i
    return None


def delimited_records(depot, text):
    seq, rows = read_delimited(depot, text)
    recs = []
    for header, row, dr in rows:
        wi = wcol(header)
        rowunit = None
        if len(row) == len(header) + 1 and wi is not None:
            cand = [i for i in (wi + 1,) if i < len(row) and row[i].strip().lower() in KG]
            if not cand:
                cand = [i for i, x in enumerate(row) if x.strip().lower() in KG]
            if cand:
                rowunit = row[cand[0]].strip().lower()
                row = row[:cand[0]] + row[cand[0] + 1:]
        if len(row) != len(header):
            continue
        r = {h: row[i] for i, h in enumerate(header)}
        idf = r.get("id") or r.get("ref") or ""
        if depot == "east" and idf.strip().upper() == "TOTAL":
            continue
        if id_num(idf) is None:
            continue
        typ = r.get("type") or r.get("kind") or r.get("typ") or r.get("rec") or r.get("t") or ""
        if depot in ("east", "west") and typ.strip().upper() == "TOTAL":
            continue
        rt = rec_type(typ)
        if depot == "harbor" and rt != "void":
            pass
        if depot in ("lakeside",) and not typ.strip():
            rt = "new"
        status = r.get("status") or r.get("state") or ""
        if depot == "harbor":
            status = HARBOR_STATE.get(status.strip().lower(), status)
        shipped = r.get("shipped") or r.get("date") or ""
        form = (dr.get("dates") or dr.get("date format") or dr.get("dates ") or "")
        if depot == "harbor":
            form = form or "iso"
        wraw = row[wi] if wi is not None else ""
        # unit resolution
        unit = unit_of(re.sub(r"^.*_", "", header[wi])) if wi is not None and "_" in header[wi] else None
        unit = unit or rowunit
        directive_unit = dr.get("unit") or dr.get("weight unit") or ""
        unit = unit or unit_of(directive_unit) or "kg"
        dc = depot == "west"
        rec = dict(num=id_num(idf), type=rt, status=norm_status(status))
        if rt != "void":
            rec["kg"] = parse_weight(wraw, unit, dc)
            rec["month"] = parse_ship(shipped, form)
        recs.append(rec)
    return seq, recs


def xml_records(text):
    text = re.sub(r"^<\?xml[^>]*\?>", "", text.lstrip())
    root = ET.fromstring(text)
    seq = root.get("seq")
    seq = int(seq) if seq and seq.isdigit() else None
    runit = (root.get("weight-unit") or root.get("unit") or "kg").lower()
    recs = []
    for sh in root.iter("shipment"):
        n = id_num(sh.get("id"))
        if n is None:
            continue
        rt = rec_type(sh.get("type") or "")
        rec = dict(num=n, type=rt)
        if rt != "void":
            w = sh.find("weight")
            unit = runit
            if sh.get("weight-unit"):
                unit = sh.get("weight-unit").lower()
            if w is not None and w.get("unit"):
                unit = w.get("unit").lower()
            kg = parse_weight(w.text if w is not None else "", unit)
            shipped = sh.get("shipped")
            c = sh.find("shipped")
            if c is not None and c.text:
                shipped = c.text
            st = sh.find("status")
            rec.update(kg=kg, month=parse_ship(shipped, None),
                       status=norm_status(st.text if st is not None else ""))
        recs.append(rec)
    return seq, recs


def json_records(text):
    seq = None
    recs = []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        try:
            v = json.loads(line)
        except ValueError:
            continue
        for o in (v if isinstance(v, list) else [v]):
            if not isinstance(o, dict):
                continue
            if "meta" in o and isinstance(o["meta"], dict):
                if seq is None and o["meta"].get("seq") is not None:
                    seq = int(o["meta"]["seq"])
                continue
            n = id_num(str(o.get("id", "")))
            if n is None:
                continue
            rt = rec_type(o.get("kind") or "")
            rec = dict(num=n, type=rt)
            if rt != "void":
                kg = None
                for k, val in o.items():
                    m = re.fullmatch(r"weight_(kg|g|lb|oz)", k)
                    if m and val is not None:
                        kg = parse_weight(str(val), m.group(1))
                rec.update(kg=kg, month=parse_ship(str(o.get("shipped_at", "")), None),
                           status=norm_status(str(o.get("status", ""))))
            recs.append(rec)
    return seq, recs


def south_records(text):
    seq = None
    layout = None
    recs = []
    for line in text.split("\n"):
        if line.startswith("#"):
            m = re.match(r"#LAYOUT\s+(\S+)", line)
            if m:
                layout = m.group(1)
            m = re.match(r"#SEQ\s+(\d+)", line)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        if "\x0c" in line or not line.strip():
            continue
        name = None
        if layout in FW and len(line) == FW[layout][0]:
            name = layout
        else:
            for k, v in FW.items():
                if len(line) == v[0]:
                    name = k
        if name is None:
            continue
        _, f, dform, wf = FW[name]
        g = {k: line[a:b] for k, (a, b) in f.items()}
        n = id_num(g["id"])
        if n is None:
            continue
        rt = rec_type(g["type"])
        rec = dict(num=n, type=rt)
        if rt != "void":
            w = Decimal(g["weight"].strip() or 0)
            if name == "FW1":
                kg = w * KG["g"]
            elif name == "FW2":
                kg = w / 100
            else:
                kg = w / 10 * KG["lb"]
            sh = g["shipped"].strip()
            if dform == "doy":
                month = parse_ship(sh, None)
            else:
                month = parse_ship(sh, None)
            rec.update(kg=kg, month=month,
                       status=FW_STATE.get(g["status"].strip().upper(), ""))
        recs.append(rec)
    return seq, recs


def load(path, depot):
    text = read_text(path)
    if depot == "central":
        return xml_records(text)
    if depot == "north":
        return json_records(text)
    if depot == "south":
        return south_records(text)
    return delimited_records(depot, text)


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if not os.path.isfile(p):
            continue
        depot = name.split("-", 1)[0]
        if depot not in ORDER:
            continue
        seq, recs = load(p, depot)
        exports.setdefault(depot, []).append((seq if seq is not None else -1, name, recs))

    corrections = resends = 0
    current = {}
    for depot, lst in exports.items():
        cur = {}
        for seq, name, recs in sorted(lst, key=lambda x: (x[0], x[1])):
            for r in recs:
                n = r["num"]
                if r["type"] == "new":
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r["type"] == "correction":
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur

    depots = {d: {"shipments": 0, "total_kg": Decimal(0)} for d in exports}
    months = {}
    handovers = 0
    nums = {}
    for d in current:
        for n in current[d]:
            nums.setdefault(n, []).append(d)
    for n, ds in nums.items():
        if len(ds) > 1:
            handovers += 1
        d = min(ds, key=ORDER.index)
        r = current[d][n]
        if r.get("status") in ("delivered", "delivered_late") and r.get("kg") is not None \
                and r.get("month"):
            depots[d]["shipments"] += 1
            depots[d]["total_kg"] += r["kg"]
            y, m = r["month"]
            e = months.setdefault("%04d-%02d" % (y, m),
                                  {"shipments": 0, "total_kg": Decimal(0)})
            e["shipments"] += 1
            e["total_kg"] += r["kg"]

    def fin(e):
        return {"shipments": e["shipments"], "total_kg": float(round(e["total_kg"], 2))}
    out = {
        "depots": {d: fin(depots[d]) for d in sorted(depots)},
        "months": {k: fin(months[k]) for k in sorted(months)},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as f:
        json.dump(out, f, indent=2)


if __name__ == "__main__":
    main()
